package com.autocare.platform.order;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.http.MediaType;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"JWT_SECRET=test-only-secret-with-at-least-32-characters","WECHAT_APP_ID=test-app"}) @AutoConfigureMockMvc class CouponTransactionsHttpTest {
 @Autowired MockMvc mvc;@MockitoBean JwtDecoder decoder;@MockitoBean CouponTransactions transactions;@MockitoBean ReservationOrders orders;@MockitoBean CouponServiceRedemption service;
 @BeforeEach void tokens(){when(decoder.decode(anyString())).thenAnswer(c->{String t=c.getArgument(0);var b=Jwt.withTokenValue(t).header("alg","HS256").subject("1").claim("jti","session").expiresAt(Instant.now().plusSeconds(600));if(t.equals("owner"))b.claim("subject_type","user").claim("role","OWNER").claim("app_id","test-app");else b.claim("subject_type","staff_account").claim("role","MERCHANT").claim("app_id","merchant-account").claim("merchant_id",1L);return b.build();});}
 String key(){return UUID.randomUUID().toString();}
 @Test void privateReadsRequireOwnerAndRoleCannotCross()throws Exception{mvc.perform(get("/api/coupon/1/service-redemption")).andExpect(status().isUnauthorized());mvc.perform(get("/api/coupon/1/service-redemption").header("Authorization","Bearer shop")).andExpect(status().isForbidden());mvc.perform(get("/api/merchant/coupons/service-redemptions").header("Authorization","Bearer owner")).andExpect(status().isForbidden());when(service.view(any(),eq(1L))).thenReturn(Map.of("user_coupon_id",1));mvc.perform(get("/api/coupon/1/service-redemption").header("Authorization","Bearer owner")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));}
 @Test void strictPreviewAndCreateCannotSubmitFinancialOverrides()throws Exception{String b="{\"merchant_project_id\":1,\"quote_version_id\":1,\"vehicle_id\":1,\"slot_id\":1,\"user_coupon_id\":1,\"publication_revision\":2,\"rule_version\":\"R5B_CASH_V1\"}";for(String raw:List.of("null",b+"{}",b.replace("\"user_coupon_id\":1","\"user_coupon_id\":1,\"user_coupon_id\":2"),b.replace("\"user_coupon_id\":1","\"user_coupon_id\":\"1\""),b.replace("R5B_CASH_V1","unknown"),b.replace("\"user_coupon_id\":1","\"user_coupon_id\":1,\"cash_amount\":\"0.00\"")))mvc.perform(post("/api/order/coupon-create").header("Authorization","Bearer owner").header("Idempotency-Key",key()).contentType(MediaType.APPLICATION_JSON).content(raw)).andExpect(status().isBadRequest());mvc.perform(post("/api/order/coupon-preview?user_id=2").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isBadRequest());verifyNoInteractions(orders,transactions);}
 @Test void strictAuthorizationBodyUuidAndQueries()throws Exception{for(String b:List.of("{}","{\"expected_revision\":-1}","{\"expected_revision\":0,\"code\":\"injected\"}","{\"expected_revision\":0,\"expected_revision\":1}"))mvc.perform(post("/api/coupon/1/service-authorization").header("Authorization","Bearer owner").header("Idempotency-Key",key()).contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());mvc.perform(post("/api/coupon/1/service-authorization").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content("{\"expected_revision\":0}")).andExpect(status().isBadRequest());mvc.perform(get("/api/merchant/coupons/service-redemptions?page=1&page=2").header("Authorization","Bearer shop")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void serviceCodeShapeAndRoleCheckedBeforeDatabase()throws Exception{for(String b:List.of("{}","{\"user_coupon_id\":1,\"authorization_revision\":1,\"code\":\"123456\"}","{\"user_coupon_id\":1,\"authorization_revision\":1,\"code\":\""+"a".repeat(32)+"\",\"commission_amount\":0}"))mvc.perform(post("/api/merchant/coupons/service-redeem").header("Authorization","Bearer shop").header("Idempotency-Key",key()).contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());mvc.perform(post("/api/merchant/coupons/service-redeem").header("Authorization","Bearer owner").header("Idempotency-Key",key()).contentType(MediaType.APPLICATION_JSON).content("{}")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void rateLimitedResponseCarriesRetryAndDatabaseFailureIsSafe()throws Exception{when(service.redeem(any(),anyString(),any())).thenThrow(new OrderRedemption.RateLimited(60));mvc.perform(post("/api/merchant/coupons/service-redeem").header("Authorization","Bearer shop").header("Idempotency-Key",key()).contentType(MediaType.APPLICATION_JSON).content("{\"user_coupon_id\":1,\"authorization_revision\":1,\"code\":\""+"a".repeat(32)+"\"}")).andExpect(status().isTooManyRequests()).andExpect(header().string("Retry-After","60"));when(service.view(any(),anyLong())).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private SQL"));mvc.perform(get("/api/coupon/1/service-redemption").header("Authorization","Bearer owner")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.message").value("券交易服务暂不可用，请保留原请求重试"));}
 @Test void merchantPreviewNeedsNoWriteKeyAndNeverDelegatesMalformedBodies()throws Exception{String b="{\"user_coupon_id\":1,\"authorization_revision\":1,\"code\":\""+"a".repeat(32)+"\"}";when(service.preview(any(),any())).thenReturn(Map.of("can_redeem",true));mvc.perform(post("/api/merchant/coupons/service-preview").header("Authorization","Bearer shop").contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(post("/api/merchant/coupons/service-preview").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isForbidden());mvc.perform(post("/api/merchant/coupons/service-preview?user_id=2").header("Authorization","Bearer shop").contentType(MediaType.APPLICATION_JSON).content(b)).andExpect(status().isBadRequest());verify(service,times(1)).preview(any(),any());}
}
